const cfg = $('Config').first().json;

function safeNodeJson(name) {
  try {
    return $(name).first()?.json ?? {};
  } catch (error) {
    return {};
  }
}

function asArray(value) {
  if (Array.isArray(value)) return value;
  return [];
}

function toNumber(value) {
  const num = Number(value ?? 0);
  return Number.isFinite(num) ? num : 0;
}

function money(value) {
  return '$' + toNumber(value).toFixed(2);
}

function percent(value) {
  return toNumber(value).toFixed(1) + '%';
}

function itemPeriodTotal(raw) {
  if (raw && typeof raw === 'object' && raw.totalAmount != null) {
    return toNumber(raw.totalAmount);
  }
  const points = asArray(raw?.points);
  return points.reduce((sum, point) => sum + toNumber(point.total), 0);
}

function itemPeriodCount(raw) {
  if (raw && typeof raw === 'object' && raw.totalCount != null) {
    return toNumber(raw.totalCount);
  }
  const points = asArray(raw?.points);
  return points.reduce((sum, point) => sum + toNumber(point.count), 0);
}

function parseTargets(items) {
  return asArray(items).map((item) => ({
    softwareName: item.softwareName ?? 'Producto',
    metaUnits: toNumber(item.metaUnits),
    unitsSoldCurrent: toNumber(item.unitsSoldCurrent),
    expectedProfit: toNumber(item.expectedProfit),
    targetAchieved: Boolean(item.targetAchieved),
    deadline: item.deadline ?? null,
  }));
}

function parseVsTargets(items) {
  return asArray(items).map((item) => ({
    softwareName: item.softwareName ?? 'Producto',
    metaUnits: toNumber(item.metaUnits),
    actualUnits: toNumber(item.actualUnits),
    varianceUnits: toNumber(item.varianceUnits),
    achieved: Boolean(item.achieved),
    deadline: item.deadline ?? null,
  }));
}

function dueDateForCurrentMonth(dueDay, now) {
  if (!dueDay || dueDay < 1) return null;
  const year = now.getFullYear();
  const month = now.getMonth();
  const lastDay = new Date(year, month + 1, 0).getDate();
  const safeDay = Math.min(dueDay, lastDay);
  const date = new Date(year, month, safeDay);
  return date;
}

function isoDate(date) {
  if (!date) return null;
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
}

const dashboard = safeNodeJson('Get Dashboard Summary');
const dailySales = safeNodeJson('Get Daily Sales');
const monthlySales = safeNodeJson('Get Monthly Sales');
const vsTargets = safeNodeJson('Get Sales Vs Targets');
const targetsSummary = safeNodeJson('Get Targets Summary');
const targetsDetail = safeNodeJson('Get Targets Detail');
const inventoryAlerts = safeNodeJson('Get Inventory Alerts');
const arList = safeNodeJson('Get Accounts Receivable');
const expensesList = safeNodeJson('Get Expenses');

const now = new Date(cfg.todayDate + 'T00:00:00');
const todayIso = cfg.todayDate;
const next3 = new Date(now);
next3.setDate(next3.getDate() + 3);
const next3Iso = isoDate(next3);

const todaySalesAmount = itemPeriodTotal(dailySales) || toNumber(dashboard.todaySalesAmount);
const todaySalesCount = itemPeriodCount(dailySales) || toNumber(dashboard.todaySalesCount);
const monthSalesAmount = itemPeriodTotal(monthlySales) || toNumber(dashboard.monthSalesAmount);
const monthSalesCount = itemPeriodCount(monthlySales) || toNumber(dashboard.monthSalesCount);
const monthProfitAmount = toNumber(dashboard.monthProfitAmount);

const totalTargetRevenue = toNumber(targetsSummary.totalTargetRevenue);
const totalExpectedProfit = toNumber(targetsSummary.totalExpectedProfit ?? dashboard.monthExpectedProfit);
const achievedTargets = toNumber(targetsSummary.achievedTargets);
const pendingTargets = toNumber(targetsSummary.pendingTargets);
const totalTargets = toNumber(targetsSummary.totalTargets);
const totalMetaUnits = toNumber(targetsSummary.totalMetaUnits);

const progressPercent = totalTargetRevenue > 0 ? (monthSalesAmount / totalTargetRevenue) * 100 : 0;
const remainingToGoal = Math.max(totalTargetRevenue - monthSalesAmount, 0);
const dayOfMonth = now.getDate();
const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
const expectedPercentToday = daysInMonth > 0 ? (dayOfMonth / daysInMonth) * 100 : 0;
const projectedClose = dayOfMonth > 0 ? (monthSalesAmount / dayOfMonth) * daysInMonth : monthSalesAmount;
const behindPlan = progressPercent < expectedPercentToday;

const targetItems = parseTargets(targetsDetail);
const vsTargetItems = parseVsTargets(vsTargets.items);

const topAchieved = vsTargetItems
  .filter((item) => item.achieved || item.actualUnits > 0)
  .sort((a, b) => b.actualUnits - a.actualUnits)
  .slice(0, 5);

const delayedTargets = vsTargetItems
  .filter((item) => !item.achieved)
  .sort((a, b) => a.varianceUnits - b.varianceUnits)
  .slice(0, 5);

const coldProducts = asArray(inventoryAlerts).slice(0, 5);

const arItems = asArray(arList);
const overdueAr = arItems.filter((item) => String(item.status || '').toUpperCase() === 'OVERDUE');
const openAr = arItems.filter((item) => String(item.status || '').toUpperCase() === 'OPEN');
const overdueArTotal = overdueAr.reduce((sum, item) => sum + toNumber(item.balance), 0);
const openArTotal = openAr.reduce((sum, item) => sum + toNumber(item.balance), 0);

const expenseItems = asArray(expensesList)
  .filter((item) => Boolean(item.active))
  .map((item) => {
    const dueDate = dueDateForCurrentMonth(toNumber(item.dueDay), now);
    return {
      name: item.name ?? 'Gasto',
      category: item.category ?? '',
      monthlyAmount: toNumber(item.monthlyAmount ?? item.totalAmount),
      dueDay: toNumber(item.dueDay),
      dueDateIso: isoDate(dueDate),
    };
  })
  .filter((item) => item.dueDateIso);

const dueTodayExpenses = expenseItems.filter((item) => item.dueDateIso === todayIso);
const overdueExpenses = expenseItems.filter((item) => item.dueDateIso < todayIso);
const next3Expenses = expenseItems.filter((item) => item.dueDateIso > todayIso && item.dueDateIso <= next3Iso);
const dueTodayExpensesTotal = dueTodayExpenses.reduce((sum, item) => sum + item.monthlyAmount, 0);
const overdueExpensesTotal = overdueExpenses.reduce((sum, item) => sum + item.monthlyAmount, 0);
const next3ExpensesTotal = next3Expenses.reduce((sum, item) => sum + item.monthlyAmount, 0);

let statusEmoji = '✅';
let priority = 'Mantener ritmo comercial, seguimiento y conversion de metas abiertas.';
if (overdueArTotal > 0 || overdueExpensesTotal > 0) {
  statusEmoji = '🚨';
  priority = 'Prioridad en liquidez: atender cartera vencida y obligaciones del mes.';
} else if (dueTodayExpensesTotal > 0) {
  statusEmoji = '⚠️';
  priority = 'Hoy hay compromisos de caja. Sostener ventas y cuidar pagos del dia.';
} else if (behindPlan || todaySalesAmount <= 0) {
  statusEmoji = '⚠️';
  priority = 'El ritmo comercial va por debajo de lo esperado. Empujar cierre y seguimiento hoy.';
}

const achievedLines = topAchieved.length
  ? topAchieved.map((item, index) => `${index + 1}. ${item.softwareName}: ${item.actualUnits}/${item.metaUnits}`).join('\n')
  : 'Sin productos con avance';

const delayedLines = delayedTargets.length
  ? delayedTargets.map((item, index) => `${index + 1}. ${item.softwareName}: faltan ${Math.abs(item.varianceUnits)} unidades`).join('\n')
  : 'Sin metas atrasadas';

const coldLines = coldProducts.length
  ? coldProducts.map((item) => `- ${item.name}`).join('\n')
  : 'Sin productos frios';

const overdueArLines = overdueAr.length
  ? overdueAr.slice(0, 5).map((item) => `- AR ${item.saleId}: ${money(item.balance)} vence ${item.dueDate ?? 's/f'}`).join('\n')
  : 'Sin cartera vencida';

const dueTodayLines = dueTodayExpenses.length
  ? dueTodayExpenses.map((item) => `- ${item.name}: ${money(item.monthlyAmount)}`).join('\n')
  : 'Sin pagos hoy';

const overdueExpenseLines = overdueExpenses.length
  ? overdueExpenses.map((item) => `- ${item.name}: ${money(item.monthlyAmount)} (dia ${item.dueDay})`).join('\n')
  : 'Sin gastos vencidos';

const next3ExpenseLines = next3Expenses.length
  ? next3Expenses.map((item) => `- ${item.name}: ${money(item.monthlyAmount)} (${item.dueDateIso})`).join('\n')
  : 'Sin pagos proximos';

const message = `📊 <b>REPORTE DIARIO DISMAL</b>\n\n` +
`Fecha: <b>${todayIso}</b>\n\n` +
`💰 <b>VENTAS</b>\n` +
`Hoy: <b>${money(todaySalesAmount)}</b> (${todaySalesCount} ventas)\n` +
`Mes: <b>${money(monthSalesAmount)}</b> (${monthSalesCount} ventas)\n` +
`Utilidad mes: <b>${money(monthProfitAmount)}</b>\n\n` +
`🎯 <b>METAS REALES DEL SISTEMA</b>\n` +
`Meta ingresos mes: <b>${money(totalTargetRevenue)}</b>\n` +
`Faltante: <b>${money(remainingToGoal)}</b>\n` +
`Avance: <b>${percent(progressPercent)}</b>\n` +
`Ritmo esperado: <b>${percent(expectedPercentToday)}</b>\n` +
`Proyeccion cierre: <b>${money(projectedClose)}</b>\n` +
`Metas logradas: <b>${achievedTargets}/${totalTargets}</b>\n` +
`Metas pendientes: <b>${pendingTargets}</b>\n` +
`Unidades meta: <b>${totalMetaUnits}</b>\n` +
`Utilidad esperada: <b>${money(totalExpectedProfit)}</b>\n\n` +
`🔥 <b>TOP AVANCE</b>\n${achievedLines}\n\n` +
`🚀 <b>METAS A EMPUJAR</b>\n${delayedLines}\n\n` +
`🧊 <b>PRODUCTOS SIN MOVIMIENTO</b>\n${coldLines}\n\n` +
`💳 <b>CARTERA</b>\n` +
`Vencida total: <b>${money(overdueArTotal)}</b> (${overdueAr.length} cuentas)\n` +
`Abierta total: <b>${money(openArTotal)}</b> (${openAr.length} cuentas)\n` +
`${overdueArLines}\n\n` +
`💸 <b>GASTOS DEL MES</b>\n` +
`Hoy: <b>${money(dueTodayExpensesTotal)}</b>\n${dueTodayLines}\n\n` +
`Vencidos: <b>${money(overdueExpensesTotal)}</b>\n${overdueExpenseLines}\n\n` +
`Proximos 3 dias: <b>${money(next3ExpensesTotal)}</b>\n${next3ExpenseLines}\n\n` +
`${statusEmoji} <b>PRIORIDAD DEL DIA</b>\n${priority}`;

return [{
  json: {
    message,
    todaySalesAmount,
    monthSalesAmount,
    totalTargetRevenue,
    progressPercent,
    expectedPercentToday,
    projectedClose,
    overdueArTotal,
    openArTotal,
    dueTodayExpensesTotal,
    overdueExpensesTotal,
    next3ExpensesTotal,
    achievedTargets,
    pendingTargets,
    topAchieved,
    delayedTargets,
    coldProducts,
    targetItems,
  }
}];
